def transform(grid):
    from collections import deque

    # 1. Identify background color (most frequent)
    counts = {}
    for row in grid:
        for val in row:
            counts[val] = counts.get(val, 0) + 1
    bg = max(counts, key=counts.get) if counts else 0

    # 2. Find connected components
    visited = set()
    components = []
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == bg or (r, c) in visited:
                continue
            color = grid[r][c]
            pixels = []
            q = deque([(r, c)])
            visited.add((r, c))

            while q:
                cr, cc = q.popleft()
                pixels.append((cr, cc))
                for dr, dc in dirs:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                        if grid[nr][nc] == color and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            q.append((nr, nc))

            components.append({
                'color': color, 'pixels': set(pixels),
                'min_r': min(x[0] for x in pixels),
                'max_r': max(x[0] for x in pixels),
                'min_c': min(x[1] for x in pixels),
                'max_c': max(x[1] for x in pixels),
                'area': len(pixels)
            })

    # 3. Sort by area to find Source
    components.sort(key=lambda x: -x['area'])

    # 4. Target: Smallest isolated component in same row as largest component
    # Or aligned vertically in column

    # Look for components that are "isolated" in rows - single pixel or line
    new_grid = [row[:] for row in grid]

    for i, target in enumerate(components):
        if target is components[0]:
            continue  # Skip source

        src = components[0]

        # Check if target is in same row/min_row as source
        if target['min_r'] == src['min_r'] or target['min_r'] + 1 == src['min_r']:
            # Check column coverage
            if target['min_c'] <= src['max_c'] and target['max_c'] >= src['min_c']:
                for r, c in target['pixels']:
                    new_grid[r][c] = src['color']

    return new_grid
